@js:
java.toast("\n 正在进行发现页更新...");
let list = [];
const push = (title, url, size) => list.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});

let itemList = [];
for (let i = 1; true; i++){
    let html = org.jsoup.Jsoup.parse(java.ajax(source.getKey() + "moviesets/" + i));
    let items = html.select("ul.grid.grid-cols-2 > li");
    if (items.size() === 0) break;
    for(let k=0;k<items.size();k++){
        itemList.push(items.get(k));
    }
}

for (let i = 0; i < itemList.length; i++) {
    let el = itemList[i];
    let a = el.select("a");
    let href = a.attr("href");
    let title = a.text();
    push(title, href + `/{{page}}`, 0.3);
}

JSON.stringify(list);

